"""Assemble RESULTS.md from results.json (so every number in the report is machine-generated)."""
import json, os, math
HERE = os.path.dirname(os.path.abspath(__file__))
R = json.load(open(os.path.join(HERE, "results.json")))
sim_path = os.path.join(HERE, "rtl", "sim_status.txt")
SIM = open(sim_path).read().strip() if os.path.exists(sim_path) else "RTL was NOT simulated (status file missing)."
T = ["test_nominal", "test_highnoise", "test_heavydrop", "test_weakfault"]
pc = lambda x: f"{100*x:.2f}"
ci = lambda p, n: 1.96 * math.sqrt(p * (1 - p) / n) * 100
sw = {r["name"]: r for r in R["sweep"]}
ex = sw["exact"]
W = R["workload"]
L = []
a = L.append
a("# PolarFire Vibration Monitor - software model results\n")
a("All numbers below are generated by `run_experiments.py` -> `results.json` -> `make_results_md.py`. **Everything is simulation on synthetic data. No hardware was touched and no PolarFire resource/power/timing figure in this file is measured.**\n")
a("## 1. What was built\n")
a("| item | file | notes |\n|---|---|---|")
a("| synthetic 32-ch generator | `vibgen.py` | healthy, imbalance, misalignment, bearing outer/inner race, looseness; speed variation; cross-channel coupling; drift/dropout; 12-bit ADC |")
a("| fixed-point feature extraction | `features.py` | RMS-energy, kurtosis, crest, 6 order-band energies (1024-pt FFT), 4 envelope-spectrum band energies + total (512-pt FFT); integer pipeline + float reference |")
a("| MLP, numpy only | `nn.py` | 448-64-32-6, Adam, ReLU; int8/int16 post-training quantisation; integer inference with pluggable multiplier LUT |")
a("| approximate multipliers + GE proxy | `approx.py` | exact, truncated(k)+constant compensation, DRUM-k, Mitchell(F); self-contained |")
a("| RTL skeleton + testbench | `rtl/approx_mul.v`, `rtl/mac_array.v`, `rtl/tb_mac_array.v`, `rtl/gen_vectors.py` | exact / truncated / DRUM modes only (no Mitchell in RTL) |")
a("| tests | `tests/` | 24 unittest cases (`python3 -m unittest discover -s tests`) |")
a("| figures | `figures/` | `pareto.png`, `confusion_int8.png`, `acc_vs_mred.png`, `generator_examples.png`, `channel_rms.png` |\n")
a("Reproduce: `python3 build_data.py` (~6 min, 2 cores) -> `python3 run_experiments.py` (~1-3 min) -> `python3 figures.py` -> `python3 make_results_md.py`; tests: `python3 -m unittest discover -s tests`; RTL: `cd rtl && ./run_sim.sh`. Python 3 + numpy + matplotlib only.\n")
a("A 1D-CNN was NOT implemented (it was optional); only the MLP exists.\n")

a("## 2. Synthetic data: assumptions (all invented, none fitted to a real machine)\n")
a("""- Sampling: fs = 8192 Hz, window N = 4096 (0.5 s), 32 accelerometers at 0-3 m along a machine train, +-8 g full scale, 12-bit ADC (3.9 mg/LSB), stored as int16 codes.
- Shaft speed 20-38 Hz (1200-2280 rpm), per-window; within the window: linear ramp (+-2% total), sinusoidal wobble (0.2-2% at 0.2-2 Hz). A tacho speed estimate with 0.3% (1 sigma) error is assumed available and is used to place the order bands.
- Bearing: 6205-like geometry (9 balls, d = 7.94 mm, D = 39.04 mm, 0 deg contact). Orders: BPFO = 3.585X, BPFI = 5.415X (BSF 2.357X, FTF 0.398X in the code docstring only; BSF/FTF faults are not generated). Impulses at BPFO/BPFI with 1% slip jitter excite a resonance (2.3-3.1 kHz, tau 0.4-1.0 ms); inner race is amplitude-modulated at 1X (depth 0.5-1.0), outer race is not.
- Imbalance: 1X dominant (+ small 2X). Misalignment: 2X dominant with 1X, 3X, 4X. Looseness: 0.5X/1.5X/2.5X sub-harmonics, many harmonics, plus clipping distortion of 1X. Fault severity uniform in [0.3, 1.0] (nominal set). Exactly one fault class per window (no combined faults).
- Background (all classes): residual 1X/2X/3X, white noise (sigma 0.03-0.12 g per window, +-20% per channel) plus a pink-ish component, 30% of windows get a 50 Hz mains pickup (this lies close to 2X for ~25 Hz shafts - a deliberate confounder), 30% get a non-synchronous 150-400 Hz tone, 15% get benign random impacts (raises kurtosis without a bearing fault).
- Coupling: each source reaches channel c with gain exp(-|pos_c - pos_src|/lambda) x U(0.4,1) and 0-3 samples of delay (lambda 0.7-1.8 m depending on source) plus adjacent-channel electrical crosstalk up to 3%.
- Sensor faults per channel per window: gain error +-7%, DC offset +-0.1 g, strong drift ramp (p = 3%, up to 1 g across the window), dropout (p = 2%: 60% flat-line, 40% burst of 5-40% of the window).
- Data sets (distinct RNG seeds, same generator => optimistic relative to reality): train @TR@ (+@VA@ validation), `test_nominal` @T1@, `test_highnoise` (noise x2.5) @T2@, `test_heavydrop` (p_drop 15%, p_drift 10%) @T3@, `test_weakfault` (severity 0.1-0.4) @T4@. Classes are balanced.
- Known geometry coincidence: 3 x BPFO = 10.75 X is within 1% of 2 x BPFI = 10.83 X, so outer-race harmonics fall inside the 2xBPFI envelope band (visible in `figures/generator_examples.png`). This is a property of the bearing, not a bug.
""")
for _k,_v in {"@TR@":R["n_train"],"@VA@":R["n_val"],"@T1@":R["n_test"]["test_nominal"],"@T2@":R["n_test"]["test_highnoise"],"@T3@":R["n_test"]["test_heavydrop"],"@T4@":R["n_test"]["test_weakfault"]}.items():
    L[-1]=L[-1].replace(_k,str(_v))

a("## 3. Features (448 per window = 32 channels x 14)\n")
a("Per channel: [0] log2(sum x^2); [1] kurtosis; [2] crest factor; [3-7] log2 band energy at 0.5X, 1X, 2X, 3X, 4-10X (+-0.15X bands, FFT of /4-decimated signal, 2 Hz bins); [8] log2 band energy 10.5X..1 kHz; [9-12] log2 envelope-spectrum energy at BPFO, 2BPFO, BPFI, 2BPFI (2-3.5 kHz 31-tap band-pass -> abs -> /8 boxcar -> 512-pt FFT, 2 Hz bins, band half-width max(3 Hz, 5%); [13] log2 total envelope-spectrum energy.\n")
a("Fixed-point choices: Q15 31-tap FIR coefficients, Q15 Hann window, radix-2 FFT with Q15 twiddles, >>1 per stage, int16 saturation, guard shifts of 4 (raw) / 5 (envelope) bits, int64 accumulators, Mitchell-style log2 with 4 fractional bits (leading-one detect + linear mantissa). RMS/kurtosis/crest use a float sqrt/divide of integer sums (a hardware divider/sqrt is not modelled).\n")
d = R["feat_fidelity"]
names = ["log2 sumsq", "kurtosis", "crest", "0.5X", "1X", "2X", "3X", "4-10X", "HF", "env BPFO", "env 2BPFO", "env BPFI", "env 2BPFI", "env total"]
a("Fixed-point vs float-reference features on `test_nominal` (live channels only):\n")
a("| feature | mean abs diff | std of feature (ref) |\n|---|---|---|")
for n, m_, s_ in zip(names, d["mean_abs_diff_per_feature"], d["feature_std_per_feature"]):
    a(f"| {n} | {m_:.3f} | {s_:.2f} |")
a(f"\nFeeding the float-reference features into the model trained on fixed-point features gives {pc(R['acc_ideal_features_into_fixedtrained_int8'])}% on `test_nominal` (int8 model, seed 0) vs {pc(R['int8_exact']['test_nominal']['per_seed'][0])}% with the fixed-point features, i.e. no measurable difference at this sample size. The standalone FFT test measures 27.7 dB SQNR for white noise of sigma 800 LSB (per-stage scaling noise).\n")

a("## 4. Model and quantisation\n")
a(f"- MLP {R['sizes']}, {R['params']:,} parameters, {R['macs_total']:,} MACs/inference ({R['macs_per_layer']}). 3 training seeds (same data), early stopping on a {R['n_val']}-window validation split. Features standardised (clip +-6 sigma); the per-feature affine standardisation is not folded into the int8 model here.")
a(f"- int8: symmetric per-tensor, weights/inputs clipped to +-127 (observed weight range {R['weight_range_int8']}, input range {R['input_range_int8']}), hidden activations 0..127 after ReLU (99.9-percentile calibration), int32/int64 accumulate, integer multiplier+shift requantisation. int16: same scheme with +-32767.\n")
a("Accuracy [%] (mean of 3 seeds; +- = sd over seeds; binomial 95% CI half-width of a single estimate in the last column):\n")
a("| set | n | float | int8 exact | int16 exact | 95% CI (+-pt) |\n|---|---|---|---|---|---|")
for t in T:
    n = R["n_test"][t]; p = R["float"][t]["mean"]
    a(f"| {t} | {n} | {pc(p)} +- {100*R['float'][t]['sd']:.2f} | {pc(R['int8_exact'][t]['mean'])} | {pc(R['int16_exact'][t]['mean'])} | {ci(p, n):.1f} |")
cm = R["confusion_int8_nominal_seed0"]
a("\nPer-class accuracy, int8 exact, `test_nominal`, seed 0: " + ", ".join(f"{c}={pc(x)}" for c, x in zip(["healthy", "imbalance", "misalignment", "bearing_outer", "bearing_inner", "looseness"], R["per_class_acc_int8_nominal_seed0"])) + f". Confusion matrix rows=true: {cm}\n")

a("## 5. Approximate multipliers in the MAC\n")
a("Operands are int8 in sign-magnitude; the multiplier core acts on 7-bit magnitudes (|x| <= 127); sign handling, accumulation (exact int) and requantisation are exact in all configurations. Approximation is applied to every multiply in all three layers (column `L1 only` = first layer only). Error metrics are exhaustive over all 128x128 magnitude pairs with a *uniform* operand distribution (not the network's actual distribution).\n")
a("**Cost proxy (NOT synthesis, NOT PolarFire LUTs).** Gate equivalents with assumed unit costs AND=1, FA=5, 2:1 MUX=2.5, FF=6, leading-one detector = 2 GE/bit. Array multiplier = (#partial-product ANDs) + 5 x (#pp bits - #output columns); truncation removes partial-product bits and columns; DRUM = 2 LOD + 2 window shifters + k x k array + shift-amount adder + output shifter; Mitchell = 2 LOD + 2 normalising shifters + log adder + antilog shifter. `MAC GE` adds a 24-bit accumulator (24 x (FA+FF)). Sign logic is omitted for all designs. The constants are textbook-order guesses; only the relative ordering is meant to be informative, and FPGA LUT-based implementations may rank designs very differently (on PolarFire, 8x8 multiplies are likely to map to hard math blocks, where truncation saves nothing).\n")
a("| design | mult GE | rel. mult | rel. MAC | MRED | NMED | bias | max abs err | nominal acc [%] (3-seed mean +- sd) | highnoise | heavydrop | weakfault | L1 only |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|")
for r in R["sweep"]:
    a(f"| {r['name']} | {r['mult_ge']:.0f} | {r['rel_mult_ge']:.2f} | {r['rel_mac_ge']:.2f} | {r['err_MRED']:.4f} | {r['err_NMED']:.4f} | {r['err_bias']:.1f} | {r['err_max_abs_err']:.0f} | {pc(r['test_nominal']['mean'])} +- {100*r['test_nominal']['sd']:.2f} | {pc(r['test_highnoise']['mean'])} | {pc(r['test_heavydrop']['mean'])} | {pc(r['test_weakfault']['mean'])} | {pc(r['L1_only_nominal'])} |")
a("\nRobustness-set columns use one model (seed 0) and n = 600, so their 95% CI is roughly +-1.7 to +-3.4 points; `L1 only` and the nominal column use n = 1200 (CI about +-1 point at 97%).\n")
a(f"Pareto-optimal designs by the plotted (noisy) accuracy: {R['pareto_rel_mult_ge']} (multiplier GE) and {R['pareto_rel_mac_ge']} (MAC GE). Because differences of up to ~1 point are inside the sampling CI, **membership of the front for designs near 97% is not statistically meaningful**; only the trend (accuracy falls clearly only for MRED >~ 0.25) is. `drum1` and `mitch0` are the same function (floor to a power of two).\n")
a("Observations (data, not claims about hardware):")
a(f"- On this proxy at 7-bit magnitudes, truncation is the only family that reduces GE meaningfully (trunc6: {sw['trunc6']['rel_mult_ge']:.2f}x multiplier GE at MRED {sw['trunc6']['err_MRED']:.3f}). DRUM and Mitchell need leading-one detectors and shifters whose proxy cost is comparable to or larger than a 7x7 array: DRUM-4 is {sw['drum4']['rel_mult_ge']:.2f}x, Mitchell F=3 is {sw['mitch3']['rel_mult_ge']:.2f}x. They are expected to pay off at wider operands; that was not tested here (int16 approximate inference was not run because a 2^15 x 2^15 LUT is infeasible).")
a("- Accuracy is very tolerant: even trunc7 (MRED 0.23) stays within about 1 point on the nominal set, while trunc8 (MRED 0.51) loses about 2 points and `weakfault` / `highnoise` degrade first. A plausible but untested explanation is that errors average out over 448-term sums and that Mitchell's one-sided (negative) bias is largely absorbed by the next layer's requantisation.")
a("- No approximation-aware retraining or fine-tuning was done; all models are exact-trained then post-training quantised.\n")

a("## 6. Workload counts (raw arithmetic, per 0.5 s window; not measured)\n")
a(f"- Front end: FIR MACs {W['fir_macs_per_window']:,}; FFT butterflies {W['fft_butterflies_per_window']:,} (~{W['fft_real_mults_per_window']:,} real multiplies at 4 per butterfly).")
a(f"- Neural network: {W['nn_macs_per_window']:,} MACs = {100*W['nn_share_of_mults']:.2f}% of all multiplies in the pipeline. With 32 MAC lanes (one per neuron, output-stationary), layer-by-layer: {W['nn_cycles_32_lanes']} cycles per inference.")
a("- Consequence: approximating only the NN multipliers can change at most ~0.5% of the multiplications of the whole system; the front end (FIR/FFT) dominates the arithmetic. Approximating the front end was not evaluated.\n")

a("## 7. RTL skeleton and testbench\n")
a("`rtl/approx_mul.v` (MODE 0 exact, 1 truncated K, 2 DRUM-K; sign-magnitude, operands in [-127,127]) and `rtl/mac_array.v` (LANES parallel MACs sharing a broadcast activation; acc <= (clear ? bias : acc) + x*w; 24-bit accumulators). `rtl/tb_mac_array.v` is self-checking: (1) exhaustive 255x255 check of exact/trunc4/trunc6/drum4/drum3 against golden values produced by `approx.py`; (2) 12 dot-product trials (8 lanes x 64 elements; trial 0 is a real slice of the quantised layer-0 weights and a real input row) for exact/trunc4/drum4. Golden vectors: `python3 rtl/gen_vectors.py`. Mitchell is not implemented in RTL. The RTL has no reset-less pipeline, no saturation, no layer sequencing/weight memory and no feature front end; it is a skeleton.\n")
a("Simulation status: " + SIM + "\n")

a("## 8. Honest caveats\n")
a("""- All data are synthetic and produced by the same generator for train and test; accuracy figures say nothing about real machines. Real vibration has non-stationary loads, gear-mesh, structural resonances, unknown geometry and sensor mounting effects not modelled here.
- Only 3 training seeds on one dataset; no confidence interval over datasets. The test sets are 600-1200 windows, so +-1 to +-3 points is sampling noise.
- The GE numbers are a transparent proxy and were not synthesised; PolarFire (LUT4 / hard multiplier / math-block) cost and power are NOT measured and may differ qualitatively.
- The tacho speed estimate is assumed to exist (order bands depend on it). No speed estimation from the vibration is modelled.
- No combined faults, no fault progression, no unseen-fault detection, no false-alarm rate analysis.
- Hardware, FPGA tools and real sensors were not used.
""")

a("## 9. Numbers for the proposal (raw numbers and reasoning only; no proposal prose)\n")
a(f"""Raw numbers
- Channels 32; fs 8192 Hz; window 4096 samples = 0.5 s; ADC 12 bit; classes 6; features/window 448.
- Network 448-64-32-6: {R['params']:,} parameters; {R['macs_total']:,} MACs/inference; int8 weights ~{R['params']/1024:.1f} KiB (+ int32 biases).
- Nominal accuracy (synthetic, n=1200): float {pc(R['float']['test_nominal']['mean'])}%, int8 {pc(R['int8_exact']['test_nominal']['mean'])}%, int16 {pc(R['int16_exact']['test_nominal']['mean'])}% (sampling CI about +-1 point).
- Stress sets (n=600 each, int8): noise x2.5 -> {pc(R['int8_exact']['test_highnoise']['mean'])}%; 15% channel dropout -> {pc(R['int8_exact']['test_heavydrop']['mean'])}%; weak faults -> {pc(R['int8_exact']['test_weakfault']['mean'])}%.
- Approximate multiplier examples (nominal acc; rel. multiplier GE proxy): exact {pc(ex['test_nominal']['mean'])}% / 1.00; trunc4 {pc(sw['trunc4']['test_nominal']['mean'])}% / {sw['trunc4']['rel_mult_ge']:.2f}; trunc6 {pc(sw['trunc6']['test_nominal']['mean'])}% / {sw['trunc6']['rel_mult_ge']:.2f}; trunc7 {pc(sw['trunc7']['test_nominal']['mean'])}% / {sw['trunc7']['rel_mult_ge']:.2f}; trunc8 {pc(sw['trunc8']['test_nominal']['mean'])}% / {sw['trunc8']['rel_mult_ge']:.2f}; drum4 {pc(sw['drum4']['test_nominal']['mean'])}% / {sw['drum4']['rel_mult_ge']:.2f}; drum3 {pc(sw['drum3']['test_nominal']['mean'])}% / {sw['drum3']['rel_mult_ge']:.2f}; mitch3 {pc(sw['mitch3']['test_nominal']['mean'])}% / {sw['mitch3']['rel_mult_ge']:.2f}.
- 32-lane MAC array, GE proxy (32 x MAC GE): exact {32*ex['mac_ge']:.0f}; trunc6 {32*sw['trunc6']['mac_ge']:.0f}; trunc7 {32*sw['trunc7']['mac_ge']:.0f}.
- Cycles per inference with 32 lanes: {W['nn_cycles_32_lanes']} (arithmetic only; at an assumed 100 MHz that would be {W['nn_cycles_32_lanes']/100:.1f} us - a hypothetical, not a measured clock).
- Front end per window: {W['fir_macs_per_window']:,} FIR MACs + ~{W['fft_real_mults_per_window']:,} FFT multiplies; NN is {100*W['nn_share_of_mults']:.2f}% of multiplies. A single multiplier at 100 MHz (assumed) would need ~{(W['fir_macs_per_window']+W['fft_real_mults_per_window']+W['nn_macs_per_window'])/100e6*1000:.0f} ms of the 500 ms window.

Reasoning (for your own wording)
- Accuracy is insensitive to multiplier error up to roughly MRED 0.1-0.25 on this synthetic task, so there is room to approximate; the nominal-set CI (about +-1 point) is larger than the observed loss for designs up to trunc7.
- Under the GE proxy only truncation saves area at 7-bit magnitudes; DRUM/Mitchell overheads (LOD, shifters) cancel the saving at this width. Whether this holds on PolarFire fabric is unmeasured and must be checked with synthesis.
- The NN is a tiny share of the pipeline's multiplies, so any system-level saving from approximating it alone is bounded by that share; the proposal's claim has to be scoped accordingly or the front end must be included in the approximation study.
- Bounds on what is claimable: synthetic data only, one dataset, 3 seeds, no hardware measurement.
""")
open(os.path.join(HERE, "RESULTS.md"), "w").write("\n".join(L))
print("RESULTS.md written")
